// ============================================================
// Lookup functions
// ============================================================

inline const TagInfo* findTag(const char* name) {
    // Binary search on all_tags (sorted by name)
    size_t lo = 0, hi = sizeof(all_tags) / sizeof(TagInfo);
    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        int cmp = strcmp(name, all_tags[mid].name);
        if (cmp == 0) return &all_tags[mid];
        if (cmp < 0) hi = mid;
        else lo = mid + 1;
    }
    return nullptr;
}

inline bool isKeywordInSet(const char* keyword, size_t set_index) {
    if (set_index >= sizeof(keyword_sets) / sizeof(KeywordSet)) return false;
    const auto& ks = keyword_sets[set_index];
    // Binary search
    size_t lo = 0, hi = ks.count;
    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        int cmp = strcmp(keyword, ks.keywords[mid]);
        if (cmp == 0) return true;
        if (cmp < 0) hi = mid;
        else lo = mid + 1;
    }
    return false;
}

inline bool isKeywordInNamespace(const char* keyword, NamespaceId ns) {
    uint8_t ns_idx = static_cast<uint8_t>(ns);
    if (ns_idx == 0 || ns_idx > sizeof(namespace_keyword_sets) / sizeof(NamespaceKeywordSets)) return false;
    const auto& nks = namespace_keyword_sets[ns_idx - 1];
    for (size_t i = 0; i < nks.count; ++i) {
        uint8_t set_id = nks.set_ids[i];
        if (set_id > 0 && set_id <= sizeof(keyword_sets) / sizeof(KeywordSet)) {
            if (isKeywordInSet(keyword, set_id - 1)) return true;
        }
    }
    return false;
}

inline const TagInfo* findTagInNamespace(const char* name, NamespaceId ns) {
    uint8_t ns_idx = static_cast<uint8_t>(ns);
    if (ns_idx == 0 || ns_idx > sizeof(namespace_tags) / sizeof(NamespaceTags)) return nullptr;
    const auto& nt = namespace_tags[ns_idx - 1];
    for (size_t i = 0; i < nt.count; ++i) {
        uint16_t tag_idx = nt.indices[i];
        if (tag_idx < sizeof(all_tags) / sizeof(TagInfo)) {
            const TagInfo* tag = &all_tags[tag_idx];
            if (strcmp(name, tag->name) == 0) return tag;
        }
    }
    return nullptr;
}

inline const TagAttribute* findTagAttributes(const char* tag_name, NamespaceId ns, size_t& out_count) {
    const TagInfo* tag = findTagInNamespace(tag_name, ns);
    if (tag) {
        out_count = tag->attr_count;
        return tag->attributes;
    }
    out_count = 0;
    return nullptr;
}

